export default function prepare({ url, fullpage }) {
  const u = new URL(url);
  if (!["http:", "https:"].includes(u.protocol)) throw Error("Use an HTTP(S) URL");
  return {
    request: { processor: "get-url-screenshot", params: { url: u.href, width: "640", fullpage } },
  };
}

