export default async function reserve(
  { submissionId, url, kind, folder, acknowledge, resolution },
  ctx,
) {
  if (
    !/^[a-zA-Z0-9_-]+$/.test(submissionId) ||
    !/^https?:\/\//i.test(url) ||
    !folder.startsWith("/")
  )
    throw Error("Invalid request");
  const key = "screenshots:" + submissionId + ":" + kind,
    old = await ctx.state.get(key),
    path = folder.replace(/\/$/, "") + "/" + submissionId + "-" + kind + ".png";
  if (old?.status === "done") throw Error("Already saved; inspect before restarting");
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect Dropbox pending " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      throw Error("Save marked confirmed; resume manually");
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { key, request: { url, path } };
}

