export default async function read({ body, key }, ctx) {
  if (body?.[".tag"] === "complete" && body.complete?.path_display) {
    await ctx.state.set(key, { status: "done", path: body.complete.path_display });
    return { ready: true, jobId: "", path: body.complete.path_display };
  }
  if (body?.[".tag"] === "async_job_id" && body.async_job_id)
    return { ready: false, jobId: body.async_job_id, path: "" };
  throw Error("Unknown Dropbox result; inspect before retrying");
}

