export default async function poll({ body, key, previous }, ctx) {
  const count = (previous?.count || 0) + 1;
  if (count > 60) throw Error("Dropbox job still pending; inspect before retrying");
  if (body?.[".tag"] === "complete" && body.complete?.path_display) {
    await ctx.state.set(key, { status: "done", path: body.complete.path_display });
    return { ready: true, path: body.complete.path_display, state: { count } };
  }
  if (body?.[".tag"] === "in_progress") return { ready: false, path: "", state: { count } };
  throw Error("Dropbox job failed or unknown; inspect before retrying");
}

