export default async function prepare(
  { submissionId, website, email, simple, full, acknowledge, resolution },
  ctx,
) {
  if (!email || !website || !simple || !full) throw Error("Missing screenshots or recipient");
  const escape = (s) =>
    String(s).replace(
      /[&<>"']/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
    );
  const key = "screenshots:" + submissionId + ":email",
    old = await ctx.state.get(key);
  if (old?.status === "done") throw Error("Email already sent");
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect email pending " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      throw Error("Email marked confirmed; stop");
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    to: email,
    subject: "Your screenshots!",
    text:
      "<p>Website: " +
      escape(website) +
      '</p><table><tr><th>Simple screenshot</th><th>Fullpage screenshot</th></tr><tr><td><img src="' +
      escape(simple) +
      '" width="320"></td><td><img src="' +
      escape(full) +
      '" width="320"></td></tr></table>',
  };
}

